    self._build(data, 1, 0, self.n - 1)

  fn _build(self, data, node, start, end):
    if start == end:
      self.tree[node] = data[start]
    el:
      let mid = (start + end) / 2
      self._build(data, 2 * node, start, mid)
      self._build(data, 2 * node + 1, mid + 1, end)
      self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

  fn update(self, idx, val):
    self._update(1, 0, self.n - 1, idx, val)

  fn _update(self, node, start, end, idx, val):
    if start == end:
      self.tree[node] = val
    el:
      let mid = (start + end) / 2
      if idx <= mid:
        self._update(2 * node, start, mid, idx, val)
      el:
        self._update(2 * node + 1, mid + 1, end, idx, val)
      self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

  fn query(self, l, r):
    ret self._query(1, 0, self.n - 1, l, r)

  fn _query(self, node, start, end, l, r):
    if r < start or end < l:
      ret 0
    if l <= start and end <= r:
      ret self.tree[node]
    let mid = (start + end) / 2
    let left_sum = self._query(2 * node, start, mid, l, r)
    let right_sum = self._query(2 * node + 1, mid + 1, end, l, r)
    ret left_sum + right_sum

class FenwickTree:
  fn init(self, n):
    self.n = n
    self.tree = [0] * (n + 1)

  fn update(self, idx, delta):
    let i = idx + 1
    while i <= self.n:
      self.tree[i] = self.tree[i] + delta
      i = i + (i & (-i))

  fn query(self, idx):
    let sum = 0
    let i = idx + 1
    while i > 0:
      sum = sum + self.tree[i]
      i = i - (i & (-i))
    ret sum

  fn range_query(self, l, r):
    ret self.query(r) - self.query(l - 1)

class DSU:
  fn init(self, n):
    self.parent = []
    self.rank = []
    let i = 0
    while i < n:
      self.parent.append(i)
      self.rank.append(0)
      i = i + 1

  fn find(self, x):
    if self.parent[x] != x:
      self.parent[x] = self.find(self.parent[x])
    ret self.parent[x]

  fn union(self, x, y):
    let px = self.find(x)
    let py = self.find(y)
    if px == py:
      ret false
    if self.rank[px] < self.rank[py]:
      self.parent[px] = py
    elif self.rank[px] > self.rank[py]:
      self.parent[py] = px
    el:
      self.parent[py] = px
      self.rank[px] = self.rank[px] + 1
    ret true

  fn connected(self, x, y):
    ret self.find(x) == self.find(y)

class KDTree:
  fn init(self, points):
    self.root = self._build(points, 0)

  fn _build(self, points, depth):
    if len(points) == 0:
      ret none
    let k = len(points[0])
    let axis = depth % k
    let sorted_points = points[:]
    let i = 0
    while i < len(sorted_points):
      let j = i + 1
      while j < len(sorted_points):
        if sorted_points[i][axis] > sorted_points[j][axis]:
          let temp = sorted_points[i]
          sorted_points[i] = sorted_points[j]
          sorted_points[j] = temp
        j = j + 1
      i = i + 1
    let mid = len(sorted_points) / 2
    ret {
      "point": sorted_points[mid],
      "left": self._build(sorted_points[:mid], depth + 1),
      "right": self._build(sorted_points[mid + 1:], depth + 1)
    }

  fn nearest(self, point):
    ret self._nearest(self.root, point, none, infinity)

  fn _nearest(self, node, point, best, best_dist):
    if node == none:
      ret [best, best_dist]
    let dist = self._distance(node["point"], point)
    if dist < best_dist:
      best = node["point"]
      best_dist = dist
    let axis = len(point) % 2
    let diff = point[axis] - node["point"][axis]
    let close = node["left"] if diff < 0 else node["right"]
    let away = node["right"] if diff < 0 else node["left"]
    [best, best_dist] = self._nearest(close, point, best, best_dist)
    if diff * diff < best_dist:
      [best, best_dist] = self._nearest(away, point, best, best_dist)
    ret [best, best_dist]

  fn _distance(self, p1, p2):
    let dist = 0
    let i = 0
    while i < len(p1):
      dist = dist + (p1[i] - p2[i]) * (p1[i] - p2[i])
      i = i + 1
    ret sqrt(dist)

class SpatialHash:
  fn init(self, cell_size):
    self.cell_size = cell_size
    self.grid = {}

  fn _hash(self, x, y):
    let cx = int(x / self.cell_size)
    let cy = int(y / self.cell_size)
    ret str(cx) + "," + str(cy)

  fn insert(self, obj, x, y, w, h):
    let min_cx = int(x / self.cell_size)
    let min_cy = int(y / self.cell_size)
    let max_cx = int((x + w) / self.cell_size)
    let max_cy = int((y + h) / self.cell_size)
    let cx = min_cx
    while cx <= max_cx:
      let cy = min_cy
      while cy <= max_cy:
        let key = str(cx) + "," + str(cy)
        if key not in self.grid:
          self.grid[key] = []
        self.grid[key].append(obj)
        cy = cy + 1
      cx = cx + 1

  fn query(self, x, y, w, h):
    let result = []
    let seen = {}
    let min_cx = int(x / self.cell_size)
    let min_cy = int(y / self.cell_size)
    let max_cx = int((x + w) / self.cell_size)
    let max_cy = int((y + h) / self.cell_size)
    let cx = min_cx
    while cx <= max_cx:
      let cy = min_cy
      while cy <= max_cy:
        let key = str(cx) + "," + str(cy)
        if key in self.grid:
          for obj in self.grid[key]:
            let obj_key = str(id(obj))
            if obj_key not in seen:
              seen[obj_key] = true
              result.append(obj)
        cy = cy + 1
      cx = cx + 1
    ret result

fn shoelace(polygon):
  let n = len(polygon)
  let area = 0
  let i = 0
  while i < n:
    let j = (i + 1) % n
    area = area + polygon[i][0] * polygon[j][1]
    area = area - polygon[j][0] * polygon[i][1]
    i = i + 1
  ret abs(area) / 2

fn convex_hull(points):
  let n = len(points)
  if n < 3:
    ret points
  let hull = []
  let leftmost = 0
  let i = 1
  while i < n:
    if points[i][0] < points[leftmost][0]:
      leftmost = i
    i = i + 1
  let p = leftmost
  while True:
    hull.append(points[p])
    let q = (p + 1) % n
    let i = 0
    while i < n:
      if orientation(points[p], points[i], points[q]) == 2:
        q = i
      i = i + 1
    p = q
    if p == leftmost:
      break
  ret hull

fn orientation(p, q, r):
  let val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
  if val == 0:
    ret 0
  ret 1 if val > 0 else 2

fn line_intersection(p1, p2, p3, p4):
  let x1 = p1[0]
  let y1 = p1[1]
  let x2 = p2[0]
  let y2 = p2[1]
  let x3 = p3[0]
  let y3 = p3[1]
  let x4 = p4[0]
  let y4 = p4[1]
  let denom = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4)
  if denom == 0:
    ret none
  let t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / denom
  let u = -((x1 - x2) * (y1 - y3) - (y1 - y2) * (x1 - x3)) / denom
  if t >= 0 and t <= 1 and u >= 0 and u <= 1:
    let x = x1 + t * (x2 - x1)
    let y = y1 + t * (y2 - y1)
    ret [x, y]
  ret none

fn circle_intersection(c1, r1, c2, r2):
  let dx = c2[0] - c1[0]
  let dy = c2[1] - c1[1]
  let d = sqrt(dx * dx + dy * dy)
  if d > r1 + r2:
    ret []
  if d < abs(r1 - r2):
    ret []
  if d == 0 and r1 == r2:
    ret []
  let a = (r1 * r1 - r2 * r2 + d * d) / (2 * d)
  let h = sqrt(r1 * r1 - a * a)
  let x2 = c1[0] + a * dx / d
  let y2 = c1[1] + a * dy / d
  let x3_1 = x2 + h * dy / d
  let y3_1 = y2 - h * dx / d
  let x3_2 = x2 - h * dy / d
  let y3_2 = y2 + h * dx / d
  if d == r1 + r2:
    ret [[x3_1, y3_1]]
  ret [[x3_1, y3_1], [x3_2, y3_2]]

fn ear_clipping(polygon):
  let n = len(polygon)
  if n < 3:
    ret []
  let indices = []
  let i = 0
  while i < n:
    indices.append(i)
    i = i + 1
  let triangles = []
  let count = n
  while count > 2:
    let ear_found = false
    let i = 0
    while i < count:
      let prev = (i - 1 + count) % count
      let curr = i
      let next = (i + 1) % count
      if is_ear(polygon, indices, prev, curr, next):
        triangles.append([indices[prev], indices[curr], indices[next]])
        indices.remove(curr)
        count = count - 1
        ear_found = true
        break
      i = i + 1
    if not ear_found:
      ret []
  ret triangles

fn is_ear(polygon, indices, prev, curr, next):
  let p = polygon[indices[prev]]
  let c = polygon[indices[curr]]
  let n = polygon[indices[next]]
  if orientation(p, c, n) != 2:
    ret false
  let i = 0
  while i < len(indices):
    if i != prev and i != curr and i != next:
      let pt = polygon[indices[i]]
      if point_in_triangle(pt, p, c, n):
        ret false
    i = i + 1
  ret true

fn voronoi(points, bounds):
  let n = len(points)
  let cells = []
  let i = 0
  while i < n:
    cells.append({"point": points[i], "vertices": []})
    i = i + 1
  let i = 0
  while i < n:
    let j = i + 1
    while j < n:
      let perp_x = (points[i][0] + points[j][0]) / 2
      let perp_y = (points[i][1] + points[j][1]) / 2
      let dx = points[j][0] - points[i][0]
      let dy = points[j][1] - points[i][1]
      let intersections = []
      let edges = [
        [[bounds[0], bounds[1]], [bounds[2], bounds[1]]],
        [[bounds[2], bounds[1]], [bounds[2], bounds[3]]],
        [[bounds[2], bounds[3]], [bounds[0], bounds[3]]],
        [[bounds[0], bounds[3]], [bounds[0], bounds[1]]]
      ]
      for edge in edges:
        let intersect = line_intersection([perp_x - dy, perp_y + dx], [perp_x + dy, perp_y - dx], edge[0], edge[1])
        if intersect != none:
          if intersect[0] >= bounds[0] and intersect[0] <= bounds[2] and intersect[1] >= bounds[1] and intersect[1] <= bounds[3]:
            intersections.append(intersect)
      if len(intersections) >= 2:
        let k = 0
        while k < len(intersections):
          cells[i]["vertices"].append(intersections[k])
          cells[j]["vertices"].append(intersections[k])
          k = k + 1
      j = j + 1
    i = i + 1
  ret cells

fn delaunay(points):
  let n = len(points)
  if n < 3:
    ret []
  let triangles = []
  let i = 0
  while i < n:
    let j = i + 1
    while j < n:
      let k = j + 1
      while k < n:
        let p1 = points[i]
        let p2 = points[j]
        let p3 = points[k]
        if is_delaunay(p1, p2, p3, points, i, j, k):
          triangles.append([i, j, k])
        k = k + 1
      j = j + 1
    i = i + 1
  ret triangles

fn is_delaunay(p1, p2, p3, points, idx1, idx2, idx3):
  let center = circumcenter(p1, p2, p3)
  let radius = distance(center, p1)
  let i = 0
  while i < len(points):
    if i != idx1 and i != idx2 and i != idx3:
      if distance(center, points[i]) < radius:
        ret false
    i = i + 1
  ret true

fn circumcenter(p1, p2, p3):
  let ax = p1[0]
  let ay = p1[1]
  let bx = p2[0]
  let by = p2[1]
  let cx = p3[0]
  let cy = p3[1]
  let d = 2 * (ax * (by - cy) + bx * (cy - ay) + cx * (ay - by))
  let ux = ((ax * ax + ay * ay) * (by - cy) + (bx * bx + by * by) * (cy - ay) + (cx * cx + cy * cy) * (ay - by)) / d
  let uy = ((ax * ax + ay * ay) * (cx - bx) + (bx * bx + by * by) * (ax - cx) + (cx * cx + cy * cy) * (bx - ax)) / d
  ret [ux, uy]

fn astar(grid, start, goal):
  let rows = len(grid)
  let cols = len(grid[0])
  let open_set = [start]
  let came_from = {}
  let g_score = {}
  let f_score = {}
  g_score[str(start)] = 0
  f_score[str(start)] = heuristic(start, goal)
  let directions = [[0, 1], [1, 0], [0, -1], [-1, 0]]
  while len(open_set) > 0:
    let current = none
    let current_f = infinity
    for node in open_set:
      let f = f_score[str(node)] or infinity
      if f < current_f:
        current_f = f
        current = node
    if current == goal:
      ret reconstruct_path(came_from, current)
    open_set.remove(current)
    for dir in directions:
      let neighbor = [current[0] + dir[0], current[1] + dir[1]]
      if neighbor[0] >= 0 and neighbor[0] < rows and neighbor[1] >= 0 and neighbor[1] < cols and grid[neighbor[0]][neighbor[1]] == 0:
        let tentative_g = (g_score[str(current)] or 0) + 1
        if tentative_g < (g_score[str(neighbor)] or infinity):
          came_from[str(neighbor)] = current
          g_score[str(neighbor)] = tentative_g
          f_score[str(neighbor)] = tentative_g + heuristic(neighbor, goal)
          if neighbor not in open_set:
            open_set.append(neighbor)
  ret []

fn heuristic(a, b):
  ret abs(a[0] - b[0]) + abs(a[1] - b[1])

fn reconstruct_path(came_from, current):
  let path = [current]
  while str(current) in came_from:
    current = came_from[str(current)]
    path.append(current)
  ret path.reverse()

fn minimax(board, depth, is_maximizing, alpha, beta):
  if depth == 0 or game_over(board):
    ret evaluate(board)
  if is_maximizing:
    let max_eval = -infinity
    for move in get_moves(board):
      make_move(board, move)
      let eval = minimax(board, depth - 1, false, alpha, beta)
      undo_move(board, move)
      max_eval = max(max_eval, eval)
      alpha = max(alpha, eval)
      if beta <= alpha:
        break
    ret max_eval
  el:
    let min_eval = infinity
    for move in get_moves(board):
      make_move(board, move)
      let eval = minimax(board, depth - 1, true, alpha, beta)
      undo_move(board, move)
      min_eval = min(min_eval, eval)
      beta = min(beta, eval)
      if beta <= alpha:
        break
    ret min_eval

class MCTS:
  fn init(self):
    self.root = {"state": none, "children": {}, "visits": 0, "wins": 0}

  def select(self, node):
    while node["children"]:
      let best_child = none
      let best_score = -infinity
      for child in node["children"].values():
        let score = child["wins"] / child["visits"] + sqrt(2 * log(node["visits"]) / child["visits"])
        if score > best_score:
          best_score = score
          best_child = child
      node = best_child
    ret node

  def expand(self, node, state):
    let moves = get_moves(state)
    for move in moves:
      let new_state = make_move(state, move)
      node["children"][move] = {"state": new_state, "children": {}, "visits": 0, "wins": 0}
    ret node["children"][moves[0]]

  def simulate(self, state):
    while not game_over(state):
      let moves = get_moves(state)
      let move = moves[random_int(0, len(moves) - 1)]
      state = make_move(state, move)
    ret evaluate(state)

  def backpropagate(self, node, result):
    while node != none:
      node["visits"] = node["visits"] + 1
      node["wins"] = node["wins"] + result
      node = node["parent"]

fn genetic_algorithm(population_size, generations, fitness_fn, mutate_fn, crossover_fn):
  let population = []
  let i = 0
  while i < population_size:
    population.append(random_individual())
    i = i + 1
  let generation = 0
  while generation < generations:
    let scores = []
    for individual in population:
      scores.append(fitness_fn(individual))
    let new_population = []
    let i = 0
    while i < population_size:
      let parent1 = tournament_select(population, scores)
      let parent2 = tournament_select(population, scores)
      let child = crossover_fn(parent1, parent2)
      child = mutate_fn(child)
      new_population.append(child)
      i = i + 1
    population = new_population
    generation = generation + 1
  let best = population[0]
  let best_score = fitness_fn(best)
  for individual in population:
    let score = fitness_fn(individual)
    if score > best_score:
      best = individual
      best_score = score
  ret best

fn tournament_select(population, scores, k):
  let best = none
  let best_score = -infinity
  let i = 0
  while i < k:
    let idx = random_int(0, len(population) - 1)
    if scores[idx] > best_score:
      best = population[idx]
      best_score = scores[idx]
    i = i + 1
  ret best

fn pso(objective_fn, bounds, num_particles, max_iter):
  let dim = len(bounds)
  let particles = []
  let velocities = []
  let personal_best = []
  let personal_best_scores = []
  let global_best = none
  let global_best_score = infinity
  let i = 0
  while i < num_particles:
    let position = []
    let velocity = []
    let j = 0
    while j < dim:
      let low = bounds[j][0]
      let high = bounds[j][1]
      position.append(random_float(low, high))
      velocity.append(random_float(-(high - low) / 10, (high - low) / 10))
      j = j + 1
    particles.append(position)
    velocities.append(velocity)
    personal_best.append(position[:])
    let score = objective_fn(position)
    personal_best_scores.append(score)
    if score < global_best_score:
      global_best = position[:]
      global_best_score = score
    i = i + 1
  let iter = 0
  while iter < max_iter:
    let i = 0
    while i < num_particles:
      let j = 0
      while j < dim:
        let r1 = random_float(0, 1)
        let r2 = random_float(0, 1)
        velocities[i][j] = velocities[i][j] + 2 * r1 * (personal_best[i][j] - particles[i][j]) + 2 * r2 * (global_best[j] - particles[i][j])
        particles[i][j] = particles[i][j] + velocities[i][j]
        if particles[i][j] < bounds[j][0]:
          particles[i][j] = bounds[j][0]
        if particles[i][j] > bounds[j][1]:
          particles[i][j] = bounds[j][1]
        j = j + 1
      let score = objective_fn(particles[i])
      if score < personal_best_scores[i]:
        personal_best[i] = particles[i][:]
        personal_best_scores[i] = score
      if score < global_best_score:
        global_best = particles[i][:]
        global_best_score = score
      i = i + 1
    iter = iter + 1
  ret global_best

fn kmeans(data, k, max_iter):
  let centroids = []
  let i = 0
  while i < k:
    centroids.append(data[random_int(0, len(data) - 1)][:])
    i = i + 1
  let clusters = []
  let iter = 0
  while iter < max_iter:
    clusters = []
    let i = 0
    while i < k:
      clusters.append([])
      i = i + 1
    for point in data:
      let min_dist = infinity
      let min_idx = 0
      let j = 0
      while j < k:
        let dist = distance(point, centroids[j])
        if dist < min_dist:
          min_dist = dist
          min_idx = j
        j = j + 1
      clusters[min_idx].append(point)
    let new_centroids = []
    let i = 0
    while i < k:
      if len(clusters[i]) > 0:
        let centroid = [0] * len(data[0])
        for point in clusters[i]:
          let j = 0
          while j < len(centroid):
            centroid[j] = centroid[j] + point[j]
            j = j + 1
        let j = 0
        while j < len(centroid):
          centroid[j] = centroid[j] / len(clusters[i])
          j = j + 1
        new_centroids.append(centroid)
      el:
        new_centroids.append(centroids[i])
      i = i + 1
    if new_centroids == centroids:
      break
    centroids = new_centroids
    iter = iter + 1
  ret {"centroids": centroids, "clusters": clusters}

fn linear_regression(x, y):
  let n = len(x)
  let sum_x = 0
  let sum_y = 0
  let sum_xy = 0
  let sum_x2 = 0
  let i = 0
  while i < n:
    sum_x = sum_x + x[i]
    sum_y = sum_y + y[i]
    sum_xy = sum_xy + x[i] * y[i]
    sum_x2 = sum_x2 + x[i] * x[i]
    i = i + 1
  let slope = (n * sum_xy - sum_x * sum_y) / (n * sum_x2 - sum_x * sum_x)
  let intercept = (sum_y - slope * sum_x) / n
  ret {"slope": slope, "intercept": intercept}

fn logistic_regression(x, y, learning_rate, epochs):
  let weights = [0] * len(x[0])
  let bias = 0
  let epoch = 0
  while epoch < epochs:
    let i = 0
    while i < len(x):
      let z = bias
      let j = 0
      while j < len(weights):
        z = z + weights[j] * x[i][j]
        j = j + 1
      let prediction = 1 / (1 + exp(-z))
      let error = prediction - y[i]
      let j = 0
      while j < len(weights):
        weights[j] = weights[j] - learning_rate * error * x[i][j]
        j = j + 1
      bias = bias - learning_rate * error
      i = i + 1
    epoch = epoch + 1
  ret {"weights": weights, "bias": bias}

class DecisionTree:
  fn init(self, max_depth):
    self.max_depth = max_depth
    self.root = none

  fn fit(self, X, y):
    self.root = self._build_tree(X, y, 0)

  fn _build_tree(self, X, y, depth):
    if depth >= self.max_depth or len(set(y)) == 1 or len(X) == 0:
      ret {"leaf": true, "value": most_common(y)}
    let best_feature = self._best_split(X, y)
    if best_feature == -1:
      ret {"leaf": true, "value": most_common(y)}
    let left_X, left_y, right_X, right_y = self._split(X, y, best_feature)
    let left = self._build_tree(left_X, left_y, depth + 1)
    let right = self._build_tree(right_X, right_y, depth + 1)
    ret {"leaf": false, "feature": best_feature, "left": left, "right": right}

  fn _best_split(self, X, y):
    let best_gini = infinity
    let best_feature = -1
    let i = 0
    while i < len(X[0]):
      let values = set([row[i] for row in X])
      for val in values:
        let left_y = [y[j] for j in range(len(y)) if X[j][i] == val]
        let right_y = [y[j] for j in range(len(y)) if X[j][i] != val]
        let gini = self._gini(left_y) * len(left_y) / len(y) + self._gini(right_y) * len(right_y) / len(y)
        if gini < best_gini:
          best_gini = gini
          best_feature = i
      i = i + 1
    ret best_feature

  fn _gini(self, y):
    if len(y) == 0:
      ret 0
    let counts = {}
    for label in y:
      counts[label] = (counts[label] or 0) + 1
    let impurity = 1
    for label in counts:
      let p = counts[label] / len(y)
      impurity = impurity - p * p
    ret impurity

  fn _split(self, X, y, feature):
    let left_X = []
    let left_y = []
    let right_X = []
    let right_y = []
    let i = 0
    while i < len(X):
      if X[i][feature] == 0:
        left_X.append(X[i])
        left_y.append(y[i])
      el:
        right_X.append(X[i])
        right_y.append(y[i])
      i = i + 1
    ret [left_X, left_y, right_X, right_y]

  fn predict(self, X):
    let predictions = []
    for x in X:
      predictions.append(self._predict_one(x, self.root))
    ret predictions

  fn _predict_one(self, x, node):
    if node["leaf"]:
      ret node["value"]
    if x[node["feature"]] == 0:
      ret self._predict_one(x, node["left"])
    el:
      ret self._predict_one(x, node["right"])

class RandomForest:
  fn init(self, n_trees, max_depth):
    self.n_trees = n_trees
    self.max_depth = max_depth
    self.trees = []

  def fit(self, X, y):
    let i = 0
    while i < self.n_trees:
      let boot_X, boot_y = bootstrap_sample(X, y)
      let tree = DecisionTree(self.max_depth)
      tree.fit(boot_X, boot_y)
      self.trees.append(tree)
      i = i + 1

  def predict(self, X):
    let predictions = []
    for tree in self.trees:
      predictions.append(tree.predict(X))
    let result = []
    let i = 0
    while i < len(X):
      let votes = {}
      for pred in predictions:
        votes[pred[i]] = (votes[pred[i]] or 0) + 1
      result.append(most_common(votes))
      i = i + 1
    ret result

fn bootstrap_sample(X, y):
  let n = len(X)
  let sample_X = []
  let sample_y = []
  let i = 0
  while i < n:
    let idx = random_int(0, n - 1)
    sample_X.append(X[idx])
    sample_y.append(y[idx])
    i = i + 1
  ret [sample_X, sample_y]

class SVM:
  fn init(self, learning_rate, iterations, lambda_param):
    self.lr = learning_rate
    self.iterations = iterations
    self.lambda_param = lambda_param
    self.weights = none
    self.bias = 0

  def fit(self, X, y):
    let n_samples = len(X)
    let n_features = len(X[0])
    self.weights = [0] * n_features
    let i = 0
    while i < self.iterations:
      let j = 0
      while j < n_samples:
        let condition = y[j] * (dot(self.weights, X[j]) + self.bias)
        if condition >= 1:
          self.weights = self.weights - self.lr * (2 * self.lambda_param * self.weights)
        el:
          self.weights = self.weights - self.lr * (2 * self.lambda_param * self.weights - y[j] * X[j])
          self.bias = self.bias + self.lr * y[j]
        j = j + 1
      i = i + 1

  def predict(self, X):
    let predictions = []
    for x in X:
      let approx = dot(self.weights, x) + self.bias
      if approx >= 0:
        predictions.append(1)
      el:
        predictions.append(-1)
    ret predictions

fn dot(a, b):
  let result = 0
  let i = 0
  while i < len(a):
    result = result + a[i] * b[i]
    i = i + 1
  ret result

class KNN:
  fn init(self, k):
    self.k = k
    self.X_train = none
    self.y_train = none

  def fit(self, X, y):
    self.X_train = X
    self.y_train = y

  def predict(self, X):
    let predictions = []
    for x in X:
      let distances = []
      let i = 0
      while i < len(self.X_train):
        distances.append([self._distance(x, self.X_train[i]), self.y_train[i]])
        i = i + 1
      let sorted_distances = sort_by(distances, d => d[0])
      let k_nearest = sorted_distances[:self.k]
      let votes = {}
      for d in k_nearest:
        votes[d[1]] = (votes[d[1]] or 0) + 1
      predictions.append(most_common(votes))
    ret predictions

  def _distance(self, x1, x2):
    let dist = 0
    let i = 0
    while i < len(x1):
      dist = dist + (x1[i] - x2[i]) * (x1[i] - x2[i])
      i = i + 1
    ret sqrt(dist)

class NaiveBayes:
  def fit(self, X, y):
    self.classes = list(set(y))
    self.priors = {}
    self.likelihoods = {}
    for c in self.classes:
      self.priors[c] = len([yi for yi in y if yi == c]) / len(y)
      let indices = [i for i in range(len(y)) if y[i] == c]
      let X_c = [X[i] for i in indices]
      self.likelihoods[c] = []
      let j = 0
      while j < len(X[0]):
        let feature_values = [X_c[i][j] for i in range(len(X_c))]
        let mean = sum(feature_values) / len(feature_values)
        let variance = sum([(x - mean) * (x - mean) for x in feature_values]) / len(feature_values)
        self.likelihoods[c].append({"mean": mean, "variance": variance})
        j = j + 1

  def predict(self, X):
    let predictions = []
    for x in X:
      let posteriors = {}
      for c in self.classes:
        posteriors[c] = log(self.priors[c])
        let j = 0
        while j < len(x):
          let mean = self.likelihoods[c][j]["mean"]
          let variance = self.likelihoods[c][j]["variance"]
          let likelihood = -0.5 * log(2 * pi * variance) - 0.5 * ((x[j] - mean) * (x[j] - mean)) / variance
          posteriors[c] = posteriors[c] + likelihood
          j = j + 1
      predictions.append(max(posteriors, key=posteriors.get))
    ret predictions

fn gradient_descent(objective_fn, gradient_fn, start, learning_rate, max_iter):
  let x = start[:]
  let iter = 0
  while iter < max_iter:
    let grad = gradient_fn(x)
    let i = 0
    while i < len(x):
      x[i] = x[i] - learning_rate * grad[i]
      i = i + 1
    iter = iter + 1
  ret x
